fn get_first_elements(lst: Vec<Vec<i32>>) -> Vec<i32> {
    // Preallocate a vector with the same length as the outer collection.
    let mut result = Vec::with_capacity(lst.len());
    // For each inner vector, take its first element.
    for inner in lst {
        // We can safely index at 0 because the problem guarantees
        // each inner vector is non-empty.
        result.push(inner[0]);
    }
    result
}

